package com.rikkeibank.customer.config;
import java.time.Duration; import org.springframework.context.annotation.*; import org.springframework.data.redis.cache.*; import org.springframework.data.redis.connection.RedisConnectionFactory; import org.springframework.data.redis.serializer.*;
@Configuration public class RedisConfig{@Bean RedisCacheManager cacheManager(RedisConnectionFactory cf){RedisCacheConfiguration c=RedisCacheConfiguration.defaultCacheConfig().entryTtl(Duration.ofMinutes(10)).disableCachingNullValues().serializeKeysWith(RedisSerializationContext.SerializationPair.fromSerializer(RedisSerializer.string())).serializeValuesWith(RedisSerializationContext.SerializationPair.fromSerializer(new JdkSerializationRedisSerializer()));return RedisCacheManager.builder(cf).cacheDefaults(c).build();}}
